#include "voltage_offsets_profile.h"
#include <cstdio>
#include <cstring>
#include <stdexcept>
using namespace druta::ui;
namespace {
int count=0;void check(bool ok,const char* message){++count;if(!ok){std::fprintf(stderr,"Offset profile %d: %s\n",__LINE__,message);throw std::runtime_error(message);}}
template<class F>void rejects(F f,const char* message){bool rejected=false;try{f();}catch(const std::exception&){rejected=true;}check(rejected,message);}
VoltageTablesData current(bool alternate=false){VoltageTablesData d;d.identity.size=sizeof(d.identity);std::strcpy(d.identity.slot,alternate?"0000:0b:00.0":"0000:04:00.0");std::strcpy(d.identity.uuid,alternate?"GPU-alternate-device":"GPU-offset-device");d.offsets_recognized=true;d.gate_enabled=false;
 for(uint32_t rail=0;rail<2;++rail)for(uint32_t field=0;field<4;++field){VoltageTableRow r;r.key={VoltageTableFamily::offsets,rail,field};r.value=static_cast<int32_t>(field)*5000-10000;r.binding="qualified-head:"+std::to_string(rail)+":"+std::to_string(field);r.availability=VoltagePolicyAvailability::available;r.writable=false;d.rows.push_back(r);}return d;}
ProfileJson python(const VoltageTablesData& d){return {
 {"schema",2},{"scope","voltage_offsets"},{"saved_at","2026-11-13"},{"saved_ts",1.25},
 {"device",{{"uuid",d.identity.uuid},{"slot",d.identity.slot},{"driver",nullptr}}},
 {"incomplete",ProfileJson::array({"unrelated unavailable original field"})},
 {"voltage_offsets",{{"slot",d.identity.slot},{"values",{{"voltage.0.REL.offset",-25000},{"voltage.0.ALT.offset",0},{"voltage.1.VMIN.offset",10000}}}}}
 };}
void tests(){for(bool alternate:{false,true}){auto data=current(alternate);const std::vector<VoltageTableKey> selected={{VoltageTableFamily::offsets,0,0},{VoltageTableFamily::offsets,1,3}};const auto native=capture_voltage_offsets_profile(data,selected);check(native["format"]=="druta-native-voltage-offsets"&&native["fields"].size()==2&&!native.contains("packets"),"Native capture contains only selected typed values and identity");const auto described=describe_voltage_offsets_profile(native);check(described.uuid==data.identity.uuid&&described.slot==data.identity.slot&&described.targets==std::vector<std::string>({"voltage:scaffold-offset:0:0","voltage:scaffold-offset:1:3"}),"Alternate identity and exact native target names");auto desired=native;desired["fields"][0]["value_uv"]=-25000;const auto staged=stage_voltage_offsets_profile(desired,data);check(staged.size()==2&&staged[0].value==-25000&&staged[0].expected==data.rows[0].value&&staged[0].binding==data.rows[0].binding&&!data.rows[0].writable&&data.gate_enabled==false,"Gate-off recognized rows stage fresh baseline without writer permission");const auto subset=select_voltage_offsets_profile(desired,{described.targets[1]});check(subset["fields"].size()==1&&stage_voltage_offsets_profile(subset,data).size()==1,"Native subset preserves selected fields");
 const auto p=python(data);const auto source=p.dump();const auto desc=describe_voltage_offsets_profile(p);check(desc.targets==std::vector<std::string>({"voltage:scaffold-offset:0:1","voltage:scaffold-offset:0:0","voltage:scaffold-offset:1:3"}),"Python canonical role names map onto offset targets");const auto requests=stage_voltage_offsets_profile(p,data);check(requests.size()==3&&requests[0].value==0&&requests[1].value==-25000&&requests[2].key.rail==1,"Released Python signed and zero values import");const auto chosen=select_voltage_offsets_profile(p,{"voltage:scaffold-offset:0:0"});check(chosen["voltage_offsets"]["values"].size()==1&&chosen["incomplete"]==p["incomplete"]&&chosen["saved_ts"]==p["saved_ts"]&&p.dump()==source,"Python subset retains metadata and source immutable");
 auto bad=p;bad["voltage_offsets"]["values"]["voltage.1.VMIN.offset"]=16777217;rejects([&]{select_voltage_offsets_profile(bad,{"voltage:scaffold-offset:0:0"});},"Discarded imprecise source value cannot bypass full validation");bad=desired;bad["fields"][1]["value_uv"]=true;rejects([&]{select_voltage_offsets_profile(bad,{described.targets[0]});},"Discarded native bool cannot bypass full validation");bad=desired;bad["fields"].push_back(bad["fields"][0]);rejects([&]{describe_voltage_offsets_profile(bad);},"Duplicate typed native targets refused");rejects([&]{select_voltage_offsets_profile(p,{"voltage:scaffold-offset:0:0","voltage:scaffold-offset:0:0"});},"Duplicate subset target refused");rejects([&]{select_voltage_offsets_profile(p,{"voltage:scaffold-offset:0:2"});},"Unknown subset target refused");
 for(const auto value:{ProfileJson(1.0),ProfileJson(true),ProfileJson(int64_t(INT32_MIN)-1),ProfileJson(uint64_t(INT32_MAX)+1),ProfileJson(16777217)}){bad=p;bad["voltage_offsets"]["values"]["voltage.0.REL.offset"]=value;rejects([&]{describe_voltage_offsets_profile(bad);},"Nonexact/int32/float32 source value refused");}
 bad=p;bad["voltage_offsets"]["values"]["voltage.01.REL.offset"]=0;rejects([&]{describe_voltage_offsets_profile(bad);},"Aliased rail key refused");bad=p;bad["voltage_offsets"]["values"]["voltage.0.OV.other"]=0;rejects([&]{describe_voltage_offsets_profile(bad);},"Unknown role key refused");bad=p;bad["packet"]="opaque";rejects([&]{describe_voltage_offsets_profile(bad);},"Opaque state cannot enter manual profile");bad=p;bad["scope"]="voltage_requests";rejects([&]{describe_voltage_offsets_profile(bad);},"Request scope cannot become offset scope");bad=p;bad["device"]["uuid"]="GPU-wrong";rejects([&]{stage_voltage_offsets_profile(bad,data);},"Supplied foreign UUID refused");bad=p;bad["voltage_offsets"]["slot"]="0000:03:00.0";rejects([&]{stage_voltage_offsets_profile(bad,data);},"Wrong saved slot refused");bad=p;bad.erase("device");check(stage_voltage_offsets_profile(bad,data).size()==3,"Historical Python profile without UUID retains exact slot contract");
 auto missing=data;missing.rows.erase(missing.rows.begin()+7);rejects([&]{stage_voltage_offsets_profile(p,missing);},"Missing selected rail/role refused independently");check(stage_voltage_offsets_profile(chosen,missing).size()==1,"Missing unrelated role does not suppress available selected offset");missing=data;missing.rows[0].stale=true;rejects([&]{stage_voltage_offsets_profile(chosen,missing);},"Stale last-good row cannot stage");missing=data;missing.offsets_recognized=false;rejects([&]{stage_voltage_offsets_profile(chosen,missing);},"Unrecognized receipt cannot stage");missing=data;missing.rows[0].binding.clear();rejects([&]{stage_voltage_offsets_profile(chosen,missing);},"Missing current binding cannot stage");missing=data;missing.rows[0].availability=VoltagePolicyAvailability::transient;rejects([&]{stage_voltage_offsets_profile(chosen,missing);},"Transient unqualified row cannot stage");
 rejects([&]{capture_voltage_offsets_profile(data,{selected[0],selected[0]});},"Duplicate capture selection refused");rejects([&]{capture_voltage_offsets_profile(data,{{VoltageTableFamily::requests,0,0}});},"Ordinary six-word request cannot enter offset capture");missing=data;missing.identity.uuid[0]=0;rejects([&]{capture_voltage_offsets_profile(missing,selected);},"Native saved profile requires UUID");
 auto limits=p;limits["voltage_offsets"]["values"]={{"voltage.0.REL.offset",INT32_MIN},{"voltage.0.OV.offset",2147483520}};check(describe_voltage_offsets_profile(limits).targets.size()==2,"Exactly float32-representable signed endpoints supported");
 }}
}
int main(){tests();std::printf("Voltage offset profiles: %d checks\n",count);return 0;}
